import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const aspect = 320 / 512;
  const height = width * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  // atlas region 0,0,512,320 out of a 512x320 atlas (region 0) -> full extent
  const atlasWidth = 512;
  const atlasHeight = 320;
  const rectX = 0, rectY = 0, rectW = 512, rectH = 320;

  const uOffset = rectX / atlasWidth;
  const vOffset = 1.0 - (rectY + rectH) / atlasHeight;
  const uScale = rectW / atlasWidth;
  const vScale = rectH / atlasHeight;

  const offsetNode = uniform(new THREE.Vector2(uOffset, vOffset));
  const scaleNode = uniform(new THREE.Vector2(uScale, vScale));

  const remappedUv = uv().mul(scaleNode).add(offsetNode);
  const texSample = texture(map, remappedUv);

  // engineered gradient tint using surface -> ink colors, subtle
  const surfaceColor = vec4(0.043, 0.043, 0.063, 1.0);
  const inkColor = vec4(0.086, 0.086, 0.114, 1.0);
  const gradientMix = mix(surfaceColor, inkColor, uv().y);

  material.colorNode = texSample.mul(0.85).add(gradientMix.mul(0.15));
  material.opacityNode = texSample.a;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.name = 'hub-journal-card-1-image';

  // billboard toward camera each frame via onBeforeRender
  mesh.onBeforeRender = function (renderer, scene, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  mesh.userData.handlers = {};

  mesh.userData.cleanup = function () {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    mesh.onBeforeRender = null;
  };

  return mesh;
}
